{
  "technical_and_design_decisions": [
    "The increment is implemented on the existing Spring XD codebase (master branch), which is built on Spring Boot and Spring Integration; development targets the project's current technology stack and Gradle build system.",
    "U2 (lazy job module lifecycle): implement bootstrap-on-launch by hooking module deployment into the job launch request path, and shut down the module context on job completion using a completion listener with reference counting so shared modules are not prematurely closed.",
    "U4 (metrics): integrate with Spring Boot Actuator's MetricRepository export() mechanism (MetricRepositoryAutoConfiguration) by implementing a metric reader/exporter inside XD containers so each deployed module/app publishes its Boot metrics to XD's monitoring channel.",
    "U5 (module options): adopt Spring Boot's configuration metadata (spring-boot-configuration-processor / configuration-metadata.json) and relaxed property binding so module options are resolved purely through Boot PropertySource ordering; XD-maintained module option metadata is removed from the core runtime classpath.",
    "U6 (externalized configuration): introduce centralized externalized configuration based on a Spring Cloud Config-style server with a Git-backed property repository; XD-Admin and XD-Container act as config clients resolving environment-specific properties at startup.",
    "U7 (Rabbit message bus performance): use the RabbitMQ management plugin plus JVM profiling and targeted throughput benchmarks (varying prefetch, ack mode, durability, concurrency, connection/channel caching) to isolate the bottleneck before applying a focused fix in the Rabbit message bus binding.",
    "U8 (CI migration): migrate Jenkins-based CI for the master branch to AWS EC2 using pre-built AMIs containing the build toolchain, with EC2 instances provisioned on demand for build agents.",
    "U1 (benchmarks): define repeatable benchmark scenarios for representative XD topologies (stream and batch), execute them on documented EC2-based cluster hardware, and publish results with full infrastructure specifics in the project's Asciidoc reference documentation.",
    "All documentation is maintained as Asciidoc in the project repository; unit and integration tests accompany every code change."
  ],
  "assumptions": [
    "A single developer performs all work; estimates are effort in work-hours, not elapsed calendar time.",
    "The existing Spring XD development environment, Gradle build, source repository, and test infrastructure are available and functional.",
    "An AWS account with permissions to create EC2 instances/AMIs and a Jenkins CI server are available for U1 and U8.",
    "RabbitMQ broker and a representative multi-node XD cluster environment are available for benchmarking and performance troubleshooting (U1, U7).",
    "All eight user stories are delivered together as one software increment; code review effort by peers is not counted since a single developer performs the work.",
    "Unit and integration testing effort is included within each development activity; no external teams or approvals block progress.",
    "Third-party library upgrades required by the changes (e.g., Spring Boot/Cloud versions) are minor and included in the activity estimates.",
    "The generic Spring Framework background in the specification (including Spring Framework 6 / Java 17) is contextual; the increment targets the existing Spring XD stack and its supported Java version."
  ],
  "activities": [
    {
      "activity_id": "U1.1",
      "activity_name": "Define benchmark scenarios and success criteria",
      "activity_description": "Select representative Spring XD stream and batch topologies, define measurable performance metrics (throughput, latency, resource usage) and acceptance criteria for the benchmark publication.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "U1.2",
      "activity_name": "Provision benchmark infrastructure",
      "activity_description": "Set up the documented benchmark environment (EC2-based XD cluster with admin, containers, message bus, and data stores) with fully recorded hardware and software specifics.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U1.3",
      "activity_name": "Implement benchmark harness and scripts",
      "activity_description": "Create repeatable load-generation and measurement scripts/harness to drive the benchmark scenarios and capture results automatically.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "U1.4",
      "activity_name": "Execute benchmark runs and collect data",
      "activity_description": "Run the benchmark scenarios, repeat for consistency, and collect/validate the performance data and resource utilization measurements.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U1.5",
      "activity_name": "Publish benchmark report with infrastructure specifics",
      "activity_description": "Write and publish the benchmark results together with complete infrastructure specifics (instance types, cluster sizes, versions, configuration) in the reference documentation.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "U2.1",
      "activity_name": "Analyze module lifecycle and design lazy bootstrap",
      "activity_description": "Analyze the current deploy-time module bootstrapping behavior and design the change so job modules are bootstrapped at job launch and shut down at job completion.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U2.2",
      "activity_name": "Implement bootstrap-on-launch for job modules",
      "activity_description": "Implement deployment/bootstrapping of the job module context when a job is launched rather than when the module is deployed.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "U2.3",
      "activity_name": "Implement shutdown-on-completion for job modules",
      "activity_description": "Implement clean shutdown of the job module context once the job completes, including handling of concurrent/shared usage.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U2.4",
      "activity_name": "Unit and integration tests for lazy module lifecycle",
      "activity_description": "Write unit and integration tests covering launch-time bootstrap, completion-time shutdown, and resource release.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "U2.5",
      "activity_name": "Fix regressions in existing job/module tests",
      "activity_description": "Update and fix existing tests and behaviors affected by the lifecycle change to keep the build green.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U3.1",
      "activity_name": "Document tap at Spark module output",
      "activity_description": "Document the Spark streaming feature for adding a tap at the Spark module output, including configuration examples.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U3.2",
      "activity_name": "Update Spark streaming examples",
      "activity_description": "Update the Spark streaming examples to reflect current features, including the tap usage at module output.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U3.3",
      "activity_name": "Document Reliable receiver",
      "activity_description": "Add documentation explaining the Reliable receiver for Spark streaming, its behavior, and configuration guidance.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U3.4",
      "activity_name": "Verify examples and review documentation",
      "activity_description": "Run the updated examples end-to-end and review the documentation for accuracy and completeness.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U4.1",
      "activity_name": "Design Boot actuator metrics integration",
      "activity_description": "Design how module/app-specific metrics from each module's Boot application context are consumed via the Boot actuator MetricRepository export() API.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U4.2",
      "activity_name": "Implement MetricRepository export() consumption",
      "activity_description": "Implement the consumption of module metrics from the Boot actuator export mechanism and their transport to XD's monitoring infrastructure.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "U4.3",
      "activity_name": "Wire module/app-specific metrics exposure",
      "activity_description": "Ensure each deployed module/app exposes its specific metrics (counters, gauges) so users gain insight into performance and usage.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U4.4",
      "activity_name": "Tests for metrics integration",
      "activity_description": "Write unit and integration tests verifying metrics are exported and consumable for representative modules.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U4.5",
      "activity_name": "Document module metrics consumption",
      "activity_description": "Document how users access and interpret module/app-specific metrics via the Boot actuator-based integration.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U5.1",
      "activity_name": "Design Boot property source-based module options",
      "activity_description": "Design the handling of module options purely via Spring Boot property source management and configuration metadata, replacing XD-maintained option metadata.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U5.2",
      "activity_name": "Implement Boot property source management for module options",
      "activity_description": "Implement option resolution using Boot's PropertySource ordering and relaxed binding so module options are injected from Boot configuration metadata.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "U5.3",
      "activity_name": "Migrate module option metadata out of XD runtime",
      "activity_description": "Remove/migrate module option metadata previously maintained in the core Spring XD runtime classpath to Boot configuration metadata shipped with modules.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "U5.4",
      "activity_name": "Tests for Boot-based module options",
      "activity_description": "Write unit and integration tests covering option injection, defaults, overriding, and metadata generation for representative modules.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "U5.5",
      "activity_name": "Update module authoring documentation",
      "activity_description": "Update module authoring docs to describe declaring module options via Boot configuration metadata instead of XD runtime metadata.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U6.1",
      "activity_name": "Design centralized externalized configuration",
      "activity_description": "Design a central place to manage external properties for applications across environments, covering server- and client-side support for XD-Admin and XD-Container.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U6.2",
      "activity_name": "Implement server-side support for XD-Admin",
      "activity_description": "Implement XD-Admin server support for resolving externalized configuration from the central configuration service.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "U6.3",
      "activity_name": "Implement server-side support for XD-Container",
      "activity_description": "Implement XD-Container server support for resolving externalized configuration from the central configuration service at startup.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "U6.4",
      "activity_name": "Implement client-side property resolution",
      "activity_description": "Implement client-side support so applications/modules consume the centrally managed, environment-specific external properties.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U6.5",
      "activity_name": "Tests for externalized configuration across environments",
      "activity_description": "Write tests validating property resolution and environment-specific overrides for XD-Admin and XD-Container.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U6.6",
      "activity_name": "Document externalized configuration",
      "activity_description": "Document how to set up and use the central externalized configuration for all environments.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U7.1",
      "activity_name": "Set up performance test and profiling environment",
      "activity_description": "Prepare an environment with RabbitMQ, monitoring/management tooling, and JVM profiling to reproduce and measure the performance issue.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U7.2",
      "activity_name": "Execute performance tests and profile Rabbit message bus",
      "activity_description": "Run throughput/latency tests with varying configurations (prefetch, ack modes, durability, concurrency) and profile the Rabbit message bus implementation.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "U7.3",
      "activity_name": "Analyze results and isolate bottleneck",
      "activity_description": "Analyze measurements and profiles to isolate the bottleneck in the Rabbit message bus implementation.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U7.4",
      "activity_name": "Implement performance fix",
      "activity_description": "Implement the appropriate fix in the Rabbit message bus (e.g., connection/channel caching, prefetch tuning, ack handling) based on the isolated bottleneck.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "U7.5",
      "activity_name": "Verify fix and document findings",
      "activity_description": "Re-run benchmarks to verify the improvement, and document root cause, fix, and recommended tuning.",
      "most_likely_effort": 8
    },
