      "activity_id": "U8.1",
      "activity_name": "Provision EC2 infrastructure for CI",
      "activity_description": "Create EC2 AMIs/images containing the build toolchain and provision the EC2 capacity for CI build agents.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U8.2",
      "activity_name": "Configure CI tooling on EC2",
      "activity_description": "Configure the CI server (Jenkins) to use EC2-based agents, including networking, credentials, and agent provisioning.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U8.3",
      "activity_name": "Migrate MASTER branch CI jobs to EC2",
      "activity_description": "Migrate all current master branch CI build jobs to run on the EC2 infrastructure.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "U8.4",
      "activity_name": "Validate and stabilize EC2 CI builds",
      "activity_description": "Validate the migrated builds, fix environment-specific failures, and stabilize the CI pipeline on EC2.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "X.1",
      "activity_name": "Increment-level integration and regression testing",
      "activity_description": "Run the full integration and regression test suite across all delivered stories to verify the complete increment.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "X.2",
      "activity_name": "Release packaging, release notes, and publishing",
      "activity_description": "Prepare release artifacts, write release notes covering all eight stories, and publish the increment and documentation.",
      "most_likely_effort": 16
    }
  ],
  "reported_total": {
    "most_likely_effort": 720
  }
}

